body {
  margin: 0;
  font-family: Inter, Arial, sans-serif;
  background: transparent;
  color: #111827;
}

.dash {
  padding: 22px;
  box-sizing: border-box;
  width: 100%;
}

.hero {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.eyebrow {
  color: #475467;
  font-size: 11px;
  font-weight: 900;
  text-transform: uppercase;
}

h1 {
  margin: 4px 0 6px;
  font-size: 34px;
  letter-spacing: 0;
}

h2 {
  margin: 0;
  font-size: 18px;
}

p {
  margin: 0;
  color: #667085;
  font-size: 13px;
}

.today {
  min-width: 170px;
  padding: 12px;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  background: #fff;
  text-align: right;
  font-weight: 800;
}

.kpis {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 18px;
}

.kpi {
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  background: #fff;
  padding: 14px;
}

.kpi span {
  display: block;
  color: #667085;
  font-size: 11px;
  text-transform: uppercase;
  font-weight: 900;
}

.kpi strong {
  display: block;
  margin-top: 8px;
  font-size: 24px;
}

.kpi em {
  display: inline-block;
  margin-top: 10px;
  font-style: normal;
  font-size: 11px;
  color: #1d4ed8;
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  padding: 4px 7px;
  border-radius: 999px;
}

.section-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  margin-bottom: 12px;
}

.section-head input {
  width: 280px;
  height: 38px;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  padding: 0 12px;
  box-sizing: border-box;
  font-weight: 600;
}

.reports {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.card {
  min-height: 132px;
  border: 1px solid #d0d5dd;
  border-radius: 8px;
  background: #fff;
  padding: 14px;
  text-align: left;
  cursor: pointer;
}

.card:hover {
  border-color: #111827;
}

.card-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 18px;
}

.badge {
  font-size: 11px;
  color: #475467;
  border: 1px solid #d0d5dd;
  border-radius: 999px;
  padding: 4px 8px;
}

.card h3 {
  margin: 0 0 7px;
  font-size: 16px;
}

.card p {
  line-height: 1.4;
}

@media (max-width: 1100px) {
  .kpis,
  .reports {
    grid-template-columns: repeat(2, 1fr);
  }
}
@media (max-width: 700px) {
  .hero,
  .section-head {
    display: block;
  }
  .today,
  .section-head input {
    width: 100%;
    margin-top: 12px;
  }
  .kpis,
  .reports {
    grid-template-columns: 1fr;
  }
}

