let reports = [];
function render(model = {}) {
  reports = model.reports || [];
  document.getElementById("subtitle").innerText = `${model.companyName || "Axon"} / ${model.warehouseName || "No warehouse"} / ${model.userName || ""}`;
  document.getElementById("today").innerText = new Date().toLocaleDateString("en-GB", {
    weekday: "long",
    year: "numeric",
    month: "short",
    day: "numeric"
  });
  document.getElementById("kpis").innerHTML = (model.kpis || []).map(kpi => `
    <div class="kpi">
      <span>${kpi.label}</span>
      <strong>${kpi.value}</strong>
      <em>${kpi.tag}</em>
    </div>
  `).join("");
  renderReports(reports);
  bindSearch();
}
function renderReports(items) {
  document.getElementById("reports").innerHTML = items.map(report => `
    <button class="card" data-action="${report.action}">
      <div class="card-top">
        <span class="badge">${report.tag}</span>
      </div>
      <h3>${report.title}</h3>
      <p>${report.text}</p>
    </button>
  `).join("");
  document.querySelectorAll(".card").forEach(card => {
    card.onclick = () => {
      appsmith.updateModel({
        selectedAction: card.dataset.action
      });
      appsmith.triggerEvent("onDashboardAction");
    };
  });
}
function bindSearch() {
  const input = document.getElementById("search");
  input.oninput = () => {
    const term = String(input.value || "").trim().toLowerCase();
    renderReports(reports.filter(report => report.title.toLowerCase().includes(term) || report.text.toLowerCase().includes(term) || report.tag.toLowerCase().includes(term)));
  };
}
appsmith.onReady(() => {
  render(appsmith.model || {});
});
appsmith.onModelChange(model => {
  render(model || {});
});

